import sys
from collections import deque

d = sys.stdin.read().split()
n, start, target = int(d[0]), int(d[1]), int(d[2])
pos = [int(x) for x in d[3:3 + n]]
bat = [int(x) for x in d[3 + n:3 + 2 * n]]
# state: (station index or -1, boost used, current capacity)
seen = {(-1, 0, start)}
dq = deque([(-1, 0, start, 0)])
ans = -1
while dq:
    i, used, cap, dist = dq.popleft()
    here = 0 if i < 0 else pos[i]
    if here + cap >= target:
        ans = dist
        break
    for j in range(i + 1, n):
        if pos[j] <= here + cap:
            for mult in (1, 2):
                if mult == 2 and used:
                    continue
                st = (j, used or mult == 2, mult * bat[j])
                if st not in seen:
                    seen.add(st)
                    dq.append((st[0], int(st[1]), st[2], dist + 1))
print(ans)

